// Every tuning number, colour and screen layout in one place. The kitchen is a fixed 1280x720
// logical canvas; the renderer scales it to the window, so no rule below depends on screen size.
// This file has no browser code and no drawing: it is the single source of truth for the rest.

export const FIELD = { width: 1280, height: 720 };

/** The fixed simulation step in seconds: 60 updates a second whatever the display's rate. */
export const STEP = 1 / 60;

/** Shift: serve this many orders, and keep the three reputation hearts you start with. */
export const SHIFT = {
  ordersToServe: 10,
  hearts: 3,
  /** Base seconds between order arrivals; it shrinks as the level climbs. */
  orderInterval: 7.5,
  orderIntervalMin: 3.4,
  orderIntervalScale: 0.92,
  /** Patience multiplier applied to each recipe at higher levels. */
  patienceScalePerLevel: 0.93,
};

export const PLAYER = {
  /** Combo window in seconds: serve the next order within this to keep the streak. */
  comboWindow: 14,
};

/** The stove: how long a cook step takes and where its "perfect" window sits. */
export const STOVE = {
  cookSeconds: 2.6,
  perfectMin: 0.55,
  perfectMax: 0.8,
  okMin: 0.4,
  okMax: 0.94,
};

export const FONT = '"Trebuchet MS", "Segoe UI", system-ui, sans-serif';

export const PALETTE = {
  backdrop: '#0b0c18',
  skyTop: '#1c2040',
  skyMid: '#171a34',
  skyBottom: '#0e1126',
  wall: '#271d35',
  wallDark: '#1f172b',
  wood: '#5b3a22',
  woodLight: '#7c5230',
  woodDark: '#3f2716',
  copper: '#c9853c',
  copperLight: '#eab56a',
  copperDark: '#8f5a24',
  ink: '#f4ebd8',
  muted: '#b3a794',
  faint: '#7d7364',
  moon: '#f6e7bd',
  moonGlow: '#f9d98c',
  plate: '#e7e2d4',
  plateRim: '#c9c2ae',
  pan: '#2b2f3a',
  panShine: '#454b5a',
  flameCore: '#ffd45e',
  flameMid: '#ff9d3c',
  flameEdge: '#e2602a',
  good: '#8fd69a',
  warn: '#e5694f',
  danger: '#d6493f',
  steam: '#c9c4e8',
  ticket: '#f3ead8',
  ticketInk: '#2a2030',
  board: '#c69a63',
  boardDark: '#9c7444',
  knife: '#d8dde4',
  knifeEdge: '#9aa4b0',
};

/** Where the pantry bins, stations and buttons sit; hit-testing and drawing both read this. */
export const LAYOUT = {
  pantry: { x: 18, y: 150, w: 288, h: 560, cols: 2, rows: 4, gap: 10 },
  worktop: { x: 320, y: 474, w: 948, h: 232 },
  stations: {
    board: { x: 336, y: 330, w: 270, h: 250 },
    stove: { x: 640, y: 330, w: 270, h: 250 },
    pass: { x: 944, y: 330, w: 300, h: 250 },
  },
  recipeCard: { x: 336, y: 152, w: 700, h: 160 },
  serveButton: { x: 944, y: 560, w: 300, h: 58 },
  orders: { x: 566, y: 10, w: 700, h: 128, slots: 3 },
  hud: { x: 20, y: 60, w: 520, h: 84 },
  title: { x: 22, y: 22 },
};

/** Names for accessibility and the HUD; the renderer draws its own art for each. */
export const INGREDIENT_NAMES = {
  salmon: 'Salmon',
  rice: 'Rice',
  nori: 'Nori',
  beef: 'Beef',
  noodles: 'Noodles',
  greens: 'Greens',
  tomato: 'Tomato',
  egg: 'Egg',
};

// The menu: ingredients, their one correct prep, and the dishes that combine them. A recipe is
// a set of ingredients (any order) rather than a fixed sequence, so the player plans a route
// through the kitchen instead of memorising a chain. Green items are chopped on the board, and
// proteins, starches and the egg are seared or cooked on the stove.

export const PREP_CHOP = 'chop';
export const PREP_COOK = 'cook';

export const INGREDIENTS = {
  salmon: { name: 'Salmon', prep: PREP_COOK },
  rice: { name: 'Rice', prep: PREP_COOK },
  nori: { name: 'Nori', prep: PREP_CHOP },
  beef: { name: 'Beef', prep: PREP_COOK },
  noodles: { name: 'Noodles', prep: PREP_COOK },
  greens: { name: 'Greens', prep: PREP_CHOP },
  tomato: { name: 'Tomato', prep: PREP_CHOP },
  egg: { name: 'Egg', prep: PREP_COOK },
};

export const INGREDIENT_IDS = Object.keys(INGREDIENTS);

/** A recipe needs each ingredient, in any order; patience is base seconds to serve it. */
export const RECIPES = {
  salmonBowl: { name: 'Moon Salmon Bowl', zh: '月港三文鱼饭', price: 42, patience: 36, ingredients: ['salmon', 'rice', 'nori'] },
  beefNoodle: { name: 'Harbor Beef Noodle', zh: '港式牛肉面', price: 46, patience: 33, ingredients: ['beef', 'noodles', 'greens'] },
  tomatoEgg: { name: 'Jade Tomato Egg Rice', zh: '翡翠番茄蛋饭', price: 38, patience: 31, ingredients: ['tomato', 'egg', 'rice'] },
  gardenRamen: { name: 'Garden Night Ramen', zh: '夜花园拉面', price: 50, patience: 37, ingredients: ['noodles', 'egg', 'nori', 'greens'] },
};

export const RECIPE_IDS = Object.keys(RECIPES);

/** The one station a prep belongs to, used for hit-testing and the player's guidance. */
export function prepStation(prep) {
  return prep === PREP_CHOP ? 'board' : 'stove';
}

// A small seeded random number generator (mulberry32). The same seed gives the same shift, so
// the screenshot scenes and any replay are repeatable and each frame is a real game state.

export function createRandom(seed) {
  let a = seed | 0;
  return function random() {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Pick one element of an array with `random()`; empty arrays are the caller's responsibility. */
export function pick(random, list) {
  return list[Math.floor(random() * list.length)];
}

// The game's rules and state, with no drawing and no browser in it: the pantry, the held
// ingredient, the cutting board, the stove, the active dish and the order rail. act() applies one
// player intent; step() advances one fixed step. Both return event flags so the caller can react
// (sound, announcements, screen changes) without the world knowing about screens or audio.

import { FIELD, LAYOUT, PLAYER, SHIFT, STEP, STOVE } from './config.js';
import { INGREDIENTS, INGREDIENT_IDS, PREP_CHOP, PREP_COOK, RECIPES, RECIPE_IDS } from './recipes.js';
import { pick } from './random.js';

export const EVENT_CHOP = 1;
export const EVENT_COOK_START = 2;
export const EVENT_COOK_GOOD = 4;
export const EVENT_PLATE = 8;
export const EVENT_SERVE = 16;
export const EVENT_SERVE_PERFECT = 32;
export const EVENT_ERROR = 64;
export const EVENT_MISS = 128;
export const EVENT_OVER = 256;
export const EVENT_WIN = 512;

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

/** Cook quality from a lift position: 2 perfect, 1 acceptable, 0 undercooked or burnt. */
function cookQuality(progress) {
  if (progress >= STOVE.perfectMin && progress <= STOVE.perfectMax) return 2;
  if (progress >= STOVE.okMin && progress <= STOVE.okMax) return 1;
  return 0;
}

export function createWorld(random) {
  const state = {
    elapsed: 0,
    level: 1,
    score: 0,
    combo: 0,
    bestCombo: 0,
    hearts: SHIFT.hearts,
    served: 0,
    over: false,
    won: false,
    held: null,
    selected: null,
    activeOrderId: null,
    nextOrderId: 1,
    orderTimer: 1.4,
    lastServeAt: -Infinity,
    orders: [],
    stove: { active: false, ingredient: null, progress: 0, phase: 'idle' },
    particles: [],
    floating: [],
    shake: 0,
    flash: 0,
    announcements: [],
  };

  function activeOrder() {
    for (let index = 0; index < state.orders.length; index += 1) {
      if (state.orders[index].id === state.activeOrderId) return state.orders[index];
    }
    return null;
  }

  function chooseActive() {
    for (let index = 0; index < state.orders.length; index += 1) {
      if (!state.orders[index].served && !state.orders[index].expired) {
        state.activeOrderId = state.orders[index].id;
        return;
      }
    }
    state.activeOrderId = null;
  }

  function pushFloating(text, x, y, color) {
    state.floating.push({ text, x, y, color, age: 0 });
  }

  function burst(x, y, color, count) {
    for (let index = 0; index < count; index += 1) {
      const angle = random() * Math.PI * 2;
      const speed = 40 + random() * 140;
      state.particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 60,
        age: 0,
        life: 0.4 + random() * 0.5,
        color,
        size: 2 + random() * 3,
      });
    }
  }

  function spawnOrder() {
    const recipeId = pick(random, RECIPE_IDS);
    const recipe = RECIPES[recipeId];
    const patienceScale = Math.pow(SHIFT.patienceScalePerLevel, state.level - 1);
    const order = {
      id: state.nextOrderId,
      recipeId,
      patience: recipe.patience * patienceScale,
      patienceMax: recipe.patience * patienceScale,
      remaining: recipe.ingredients.slice(),
      dish: {},
      assembled: false,
      served: false,
      expired: false,
    };
    state.nextOrderId += 1;
    state.orders.push(order);
    if (state.activeOrderId === null) state.activeOrderId = order.id;
    if (state.orders.length > 3) {
      // The rail holds three tickets; the oldest beyond that is dropped as a missed order.
      let oldestIndex = -1;
      let oldestPatience = Infinity;
      for (let index = 0; index < state.orders.length; index += 1) {
        const candidate = state.orders[index];
        if (!candidate.served && !candidate.expired && candidate.patience < oldestPatience) {
          oldestPatience = candidate.patience;
          oldestIndex = index;
        }
      }
      if (oldestIndex >= 0) missOrder(state.orders[oldestIndex]);
    }
  }

  function addIngredient(ingredient, quality) {
    const order = activeOrder();
    if (!order) return false;
    const index = order.remaining.indexOf(ingredient);
    if (index < 0) {
      // The dish already has it (or it was never part of it): tolerate and keep the item.
      state.shake = 0.25;
      return false;
    }
    order.remaining.splice(index, 1);
    order.dish[ingredient] = quality;
    if (order.remaining.length === 0) {
      order.assembled = true;
    }
    return true;
  }

  function serveOrder(order) {
    const recipe = RECIPES[order.recipeId];
    const timeFactor = clamp(order.patience / order.patienceMax, 0, 1);
    let qualitySum = 0;
    let qualityCount = 0;
    for (const ingredient of recipe.ingredients) {
      const quality = ingredient in order.dish ? order.dish[ingredient] : 1;
      qualitySum += quality;
      qualityCount += 1;
    }
    const quality = qualityCount > 0 ? qualitySum / qualityCount : 1;
    const perfect = quality >= 1.9;
    const tip = Math.round(recipe.price * (0.15 + 0.5 * timeFactor) + quality * 3);
    const now = state.elapsed;
    state.combo = now - state.lastServeAt <= PLAYER.comboWindow ? state.combo + 1 : 1;
    state.lastServeAt = now;
    if (state.combo > state.bestCombo) state.bestCombo = state.combo;
    const multiplier = 1 + Math.min(state.combo - 1, 5) * 0.12;
    const gained = Math.round((recipe.price + tip) * multiplier);
    state.score += gained;
    state.served += 1;
    order.served = true;
    const pass = LAYOUT.stations.pass;
    pushFloating(`+${gained}`, pass.x + pass.w / 2, pass.y - 8, '#f6e7bd');
    if (state.combo > 1) pushFloating(`COMBO x${state.combo}`, pass.x + pass.w / 2, pass.y - 40, '#eab56a');
    burst(pass.x + pass.w / 2, pass.y + 90, '#eab56a', 18);
    if (state.served >= SHIFT.ordersToServe) {
      state.won = true;
      state.over = true;
      return perfect ? (EVENT_SERVE | EVENT_SERVE_PERFECT | EVENT_WIN) : (EVENT_SERVE | EVENT_WIN);
    }
    if (state.activeOrderId === order.id) chooseActive();
    return perfect ? (EVENT_SERVE | EVENT_SERVE_PERFECT) : EVENT_SERVE;
  }

  function missOrder(order) {
    order.expired = true;
    state.hearts -= 1;
    state.combo = 0;
    const rail = LAYOUT.orders;
    pushFloating('MISSED', rail.x + rail.w / 2, rail.y + rail.h + 18, '#e5694f');
    burst(rail.x + rail.w / 2, rail.y + 40, '#e5694f', 10);
    if (state.activeOrderId === order.id) chooseActive();
    if (state.hearts <= 0) {
      state.over = true;
      state.won = false;
    }
  }

  function startCook() {
    state.stove.active = true;
    state.stove.ingredient = state.held;
    state.stove.progress = 0;
    state.stove.phase = 'cooking';
    state.held = null;
  }

  function liftCook() {
    const quality = cookQuality(state.stove.progress);
    const ingredient = state.stove.ingredient;
    state.stove.active = false;
    state.stove.ingredient = null;
    state.stove.progress = 0;
    state.stove.phase = 'idle';
    if (addIngredient(ingredient, quality)) {
      const stove = LAYOUT.stations.stove;
      if (quality === 2) {
        burst(stove.x + stove.w / 2, stove.y + 70, '#8fd69a', 14);
        pushFloating('PERFECT', stove.x + stove.w / 2, stove.y + 24, '#8fd69a');
      } else if (quality === 0) {
        pushFloating('BURNT', stove.x + stove.w / 2, stove.y + 24, '#d6493f');
        state.shake = 0.2;
      }
      return quality >= 1 ? EVENT_COOK_GOOD : EVENT_COOK_START;
    }
    return EVENT_ERROR;
  }

  /**
   * Apply one intent. Returns event flags; 0 when the intent changed nothing visible.
   */
  function act(intent) {
    if (state.over) return 0;
    if (intent.type === 'select') {
      state.selected = intent.ingredient;
      state.held = intent.ingredient;
      return 0;
    }
    if (intent.type === 'station') {
      if (intent.station === 'stove' && state.stove.active) return liftCook();
      if (state.held === null) {
        state.shake = 0.15;
        return EVENT_ERROR;
      }
      const prep = INGREDIENTS[state.held].prep;
      if (intent.station === 'board' && prep === PREP_CHOP) {
        const board = LAYOUT.stations.board;
        const ingredient = state.held;
        state.held = null;
        if (addIngredient(ingredient, 2)) {
          burst(board.x + board.w / 2, board.y + 90, '#c9e6a8', 12);
          return EVENT_CHOP;
        }
        return EVENT_ERROR;
      }
      if (intent.station === 'stove' && prep === PREP_COOK) {
        startCook();
        return EVENT_COOK_START;
      }
      state.shake = 0.2;
      return EVENT_ERROR;
    }
    if (intent.type === 'serve') {
      const order = activeOrder();
      if (!order) return EVENT_ERROR;
      if (order.assembled) return serveOrder(order);
      state.shake = 0.15;
      return EVENT_ERROR;
    }
    return 0;
  }

  /** One fixed step. Returns event flags for things that happened during the tick. */
  function step(dt) {
    let events = 0;
    if (state.over) return events;

    state.elapsed += dt;
    state.level = Math.min(8, 1 + Math.floor(state.elapsed / 18));

    state.orderTimer -= dt;
    if (state.orderTimer <= 0) {
      spawnOrder();
      const interval = Math.max(SHIFT.orderIntervalMin, SHIFT.orderInterval * Math.pow(SHIFT.orderIntervalScale, state.level - 1));
      state.orderTimer += interval;
    }

    for (let index = state.orders.length - 1; index >= 0; index -= 1) {
      const order = state.orders[index];
      if (order.served || order.expired) continue;
      order.patience -= dt;
      if (order.patience <= 0) {
        missOrder(order);
        events |= EVENT_MISS;
      }
    }
    state.orders = state.orders.filter((order) => !order.served && !order.expired);

    if (state.stove.active) {
      state.stove.progress += dt / STOVE.cookSeconds;
      if (state.stove.progress >= 1) {
        events |= liftCook();
      }
    }

    for (let index = state.particles.length - 1; index >= 0; index -= 1) {
      const particle = state.particles[index];
      particle.age += dt;
      if (particle.age >= particle.life) {
        state.particles.splice(index, 1);
        continue;
      }
      particle.x += particle.vx * dt;
      particle.y += particle.vy * dt;
      particle.vy += 320 * dt;
    }
    for (let index = state.floating.length - 1; index >= 0; index -= 1) {
      const item = state.floating[index];
      item.age += dt;
      item.y -= 46 * dt;
      if (item.age >= 1.1) state.floating.splice(index, 1);
    }
    state.shake = Math.max(0, state.shake - dt * 2.2);
    state.flash = Math.max(0, state.flash - dt * 3);

    if (state.over && !state.won) events |= EVENT_OVER;
    return events;
  }

  function reset() {
    state.elapsed = 0;
    state.level = 1;
    state.score = 0;
    state.combo = 0;
    state.bestCombo = 0;
    state.hearts = SHIFT.hearts;
    state.served = 0;
    state.over = false;
    state.won = false;
    state.held = null;
    state.selected = null;
    state.activeOrderId = null;
    state.nextOrderId = 1;
    state.orderTimer = 1.4;
    state.lastServeAt = -Infinity;
    state.orders = [];
    state.stove = { active: false, ingredient: null, progress: 0, phase: 'idle' };
    state.particles = [];
    state.floating = [];
    state.shake = 0;
    state.flash = 0;
  }

  reset();
  return { state, reset, step, act };
}

// Keyboard and pointer input. The game is mouse-first: every station and pantry bin is a click
// target, and the keyboard offers the same moves (1-8 for ingredients, B for the board, C for the
// stove, Space to plate/serve, M to mute, P to pause). This file turns raw events into semantic
// intents and never knows the rules, so the world stays about cooking.

import { LAYOUT } from './config.js';
import { INGREDIENT_IDS } from './recipes.js';
import { unlock } from './audio.js';

const INGREDIENT_KEYS = new Set(['Digit1', 'Digit2', 'Digit3', 'Digit4', 'Digit5', 'Digit6', 'Digit7', 'Digit8']);

function pointInRect(x, y, rect) {
  return x >= rect.x && x <= rect.x + rect.w && y >= rect.y && y <= rect.y + rect.h;
}

/** The pantry bin (0..7) at a logical point, or -1 when the point is outside the bins. */
function binAt(x, y) {
  const p = LAYOUT.pantry;
  const cellW = (p.w - p.gap * (p.cols + 1)) / p.cols;
  const cellH = (p.h - p.gap * (p.rows + 1)) / p.rows;
  for (let index = 0; index < INGREDIENT_IDS.length; index += 1) {
    const col = Math.floor(index / p.rows);
    const row = index % p.rows;
    const bx = p.x + p.gap + col * (cellW + p.gap);
    const by = p.y + p.gap + row * (cellH + p.gap);
    if (x >= bx && x <= bx + cellW && y >= by && y <= by + cellH) return index;
  }
  return -1;
}

export function createInput(target, view) {
  let pointer = null;
  const clicks = [];
  const actions = [];
  let hover = null;

  function logical(clientX, clientY) {
    const rect = target.getBoundingClientRect();
    return {
      x: (clientX - rect.left - view.x) / view.scale,
      y: (clientY - rect.top - view.y) / view.scale,
    };
  }

  window.addEventListener('pointermove', (event) => {
    const point = logical(event.clientX, event.clientY);
    pointer = point;
    hover = {
      bin: binAt(point.x, point.y),
      station: null,
      button: false,
    };
    for (const name of Object.keys(LAYOUT.stations)) {
      if (pointInRect(point.x, point.y, LAYOUT.stations[name])) hover.station = name;
    }
    if (pointInRect(point.x, point.y, LAYOUT.serveButton)) hover.button = true;
  });

  window.addEventListener('pointerdown', (event) => {
    const point = logical(event.clientX, event.clientY);
    pointer = point;
    unlock();
    const bin = binAt(point.x, point.y);
    if (bin >= 0) {
      actions.push({ type: 'select', ingredient: INGREDIENT_IDS[bin] });
      event.preventDefault();
      return;
    }
    for (const name of Object.keys(LAYOUT.stations)) {
      if (pointInRect(point.x, point.y, LAYOUT.stations[name])) {
        actions.push({ type: 'station', station: name });
        event.preventDefault();
        return;
      }
    }
    if (pointInRect(point.x, point.y, LAYOUT.serveButton)) {
      actions.push({ type: 'serve' });
      event.preventDefault();
      return;
    }
    clicks.push(point);
  });

  window.addEventListener('keydown', (event) => {
    if (INGREDIENT_KEYS.has(event.code)) {
      const index = Number(event.code.slice(5)) - 1;
      if (index < INGREDIENT_IDS.length) {
        actions.push({ type: 'select', ingredient: INGREDIENT_IDS[index] });
        unlock();
      }
    } else if (event.code === 'KeyB') {
      actions.push({ type: 'station', station: 'board' });
      unlock();
    } else if (event.code === 'KeyC' || event.code === 'KeyS') {
      actions.push({ type: 'station', station: 'stove' });
      unlock();
    } else if (event.code === 'Space' || event.code === 'Enter') {
      actions.push({ type: 'serve' });
      unlock();
    } else if (event.code === 'KeyM') {
      actions.push({ type: 'mute' });
    } else if (event.code === 'KeyP' || event.code === 'Escape') {
      actions.push({ type: 'pause' });
    } else return;
    event.preventDefault();
  });

  return {
    /** The logical hover state, or null when the pointer has not moved yet. */
    hover() {
      return hover;
    },
    /** Take every intent queued since the last call. */
    take() {
      const taken = actions.slice();
      actions.length = 0;
      clicks.length = 0;
      return taken;
    },
    pointer() {
      return pointer;
    },
  };
}

// Small synthesized sound: every effect is a few oscillator blips, so the game ships no audio
// files and loads nothing. The AudioContext is created lazily on the first user gesture (browsers
// mute it otherwise), and every call is guarded, so a missing or blocked context never breaks play.

let context = null;
let master = null;
let muted = false;

function ensure() {
  if (context) return;
  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return;
    context = new AudioContextClass();
    master = context.createGain();
    master.gain.value = 0.5;
    master.connect(context.destination);
  } catch {
    context = null;
  }
}

function tone(frequency, start, duration, type, gain) {
  if (!context || muted) return;
  try {
    const osc = context.createOscillator();
    const env = context.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, context.currentTime + start);
    env.gain.setValueAtTime(0.0001, context.currentTime + start);
    env.gain.exponentialRampToValueAtTime(gain, context.currentTime + start + 0.008);
    env.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + start + duration);
    osc.connect(env);
    env.connect(master);
    osc.start(context.currentTime + start);
    osc.stop(context.currentTime + start + duration + 0.02);
  } catch {
    // A blocked or closed context is never an error the game cares about.
  }
}

function noise(duration, gain) {
  if (!context || muted) return;
  try {
    const length = Math.max(1, Math.floor(context.sampleRate * duration));
    const buffer = context.createBuffer(1, length, context.sampleRate);
    const data = buffer.getChannelData(0);
    for (let index = 0; index < length; index += 1) data[index] = (Math.random() * 2 - 1) * (1 - index / length);
    const source = context.createBufferSource();
    const env = context.createGain();
    env.gain.value = gain;
    const filter = context.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 900;
    source.buffer = buffer;
    source.connect(filter);
    filter.connect(env);
    env.connect(master);
    source.start();
  } catch {
    // Ignored, as above.
  }
}

/** Call from a pointer or key handler: browsers need a gesture before sound may start. */
export function unlock() {
  ensure();
  if (context && context.state === 'suspended') {
    context.resume().catch(() => {});
  }
}

export function setMuted(value) {
  muted = value;
}

export function chop() {
  ensure();
  tone(320, 0, 0.07, 'square', 0.16);
  tone(160, 0.015, 0.09, 'square', 0.12);
