import { SHIFT, STEP } from './config.js';
import { createRandom } from './random.js';
import { createWorld, EVENT_CHOP, EVENT_COOK, EVENT_COOK_DONE, EVENT_ERROR, EVENT_MISS, EVENT_OVER, EVENT_PLATE, EVENT_SERVE, EVENT_WIN } from './world.js';
import { createInput } from './input.js';
import { createRenderer, SCREEN_PLAY, SCREEN_TITLE } from './render.js';
import { createAudio } from './audio.js';
import { stageShot } from './shots.js';

const BEST_KEY = 'moonlit-mise-best';
const MAX_FRAME = 0.25;

const params = new URLSearchParams(window.location.search);
const shot = params.get('shot');
const seedParam = Number.parseInt(params.get('seed') ?? '', 10);
const seed = Number.isInteger(seedParam) ? seedParam : Math.floor(Math.random() * 4294967296);

const canvas = document.getElementById('game');
const status = document.getElementById('status');
const world = createWorld(createRandom(seed));
const renderer = createRenderer(canvas);

function readBest() { try { return Number.parseInt(window.localStorage.getItem(BEST_KEY) ?? '0', 10) || 0; } catch { return 0; } }
function saveBest(value) { try { window.localStorage.setItem(BEST_KEY, String(value)); } catch {} }

function runShot(name) { ... }

function runGame() {
  const input = createInput(canvas);
  const audio = createAudio();
  let screen = SCREEN_TITLE;
  let best = readBest();
  let accumulator = 0;
  let last = performance.now();
  let paused = false;

  function announce(message) { status.textContent = message; }

  window.addEventListener('pointerdown', () => audio.unlock());
  window.addEventListener('keydown', () => audio.unlock());

  function startGame() {
    world.reset();
    world.state.phase = 'play';
    screen = SCREEN_TITLE? no, SCREEN_PLAY.
    screen = 'play';
    paused = false;
    accumulator = 0;
    announce(`Shift started. Serve ${SHIFT.ordersToServe} orders.`);
  }

  function endGame() {
    screen = 'over';
    if (world.state.score > best) { best = world.state.score; saveBest(best); }
    announce(world.state.won ? `Shift complete. Score ${world.state.score}.` : `Out of hearts. Score ${world.state.score}.`);
  }

  function playSound(events) {
    if (events & EVENT_CHOP) audio.play('chop');
    if (events & EVENT_COOK) audio.play('cook');
    if (events & EVENT_COOK_DONE) audio.play('plate');
    if (events & EVENT_PLATE) audio.play('plate');
    if (events & EVENT_SERVE) audio.play('serve');
    if (events & EVENT_MISS) audio.play('miss');
    if (events & EVENT_ERROR) audio.play('miss');
  }

  function frame(now) {
    requestAnimationFrame(frame);
    accumulator += Math.min((now - last) / 1000, MAX_FRAME);
    last = now;

    const actions = input.takeActions();
    if (screen === 'title' || screen === 'over') {
      if (actions.confirm) startGame();
      accumulator = 0;
    } else {
      if (actions.pause) {
        paused = !paused;
        announce(paused ? 'Paused.' : 'Playing.');
        accumulator = 0;
      } else if (!paused) {
        let pending = actions;
        while (accumulator >= STEP) {
          const events = world.step(STEP, pending);
          if (events) playSound(events);
          if (events & EVENT_OVER) endGame();
          pending = { take: [], placeAt: [], plate: false, serve: false, removeLast: false };
          accumulator -= STEP;
        }
      } else {
        accumulator = 0;
      }
    }
    renderer.draw(world.state, screen, best);
  }

  document.addEventListener('visibilitychange', () => {
    if (document.hidden && screen === 'play' && !paused) {
      paused = true;
      announce('Paused.');
    }
  });

  announce('Moonlit Mise. Press Space or click to start.');
  requestAnimationFrame(frame);
}

if (shot) runShot(shot);
else runGame();
```

